public record RangedCoRule(string WeaponId,int AttackIndex,string Mode,double Ratio,bool MultishotIndependent=false,double ExtraProjectileRatio=1);
public record RangedCoCatalog(WikiSource Source,RangedCoRule[] Rules)
{
    public static readonly RangedCoCatalog Data=Load();
    private static RangedCoCatalog Load(){using var s=Assembly.GetExecutingAssembly().GetManifestResourceStream("TennoForge.Core.ranged-co.json")!;return JsonSerializer.Deserialize<RangedCoCatalog>(s,Catalog.Json)!;}
    public static RangedCoRule Get(ReferenceWeapon w,int attack)=>w.Id==RangedPullWeapons.Proboscis&&attack>0?new(w.Id,attack,"None",0):RangedVileDischarge.Applies(w)&&attack==1?new(w.Id,attack,"Multiplicative",1):Data.Rules.SingleOrDefault(r=>r.WeaponId==w.Id&&r.AttackIndex==attack)??new(w.Id,attack,RangedEngine.S(RangedEngine.Attacks(w)[attack],"ShotType")=="AoE"?"None":"Additive",1);
}
